def is_power_of_two(n):
    return (n > 0) and (n & (n - 1)) == 0

def nth_polite_number(n):
    count = 0
    num = 1
    while count < n:
        if not is_power_of_two(num):
            count += 1
            if count == n:
                return num
        num += 1

def is_polite(n):
    return nth_polite_number(n)

# Testing the function
assert is_polite(1) == 3  # The 1st polite number
assert is_polite(2) == 5  # The 2nd polite number
assert is_polite(3) == 6  # The 3rd polite number
assert is_polite(7) == 11 # The 7th polite number
