def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. In case of overlapping keys, values from the
    last dictionary in the sequence take precedence.
    """
    # Create a new dictionary and update it with all three dictionaries in order
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)
    return merged_dict

# Example tests:
assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "O": "Orange", "W": "White", "B": "Black" }
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    {"L": "lavender", "B": "Blue"}
) == {'R': 'Red', 'B': 'Blue', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}

assert merge_dictionaries_three(
    {},
    { "A": "Apple" },
    { "B": "Banana" }
) == {'A': 'Apple', 'B': 'Banana'}

assert merge_dictionaries_three(
    {},
    {},
    {}
) == {}
